namespace Game.AI.Actions
{
    /// <summary>
    /// 敵AIが実行可能な行動の種類。
    /// </summary>
    public enum MazeEnemyActionType
    {
        /// <summary>
        /// 行動未指定。
        /// </summary>
        None = 0,

        /// <summary>
        /// 待機する。
        /// </summary>
        Idle = 100,

        /// <summary>
        /// 指定された地点を巡回する。
        /// </summary>
        Patrol = 200,

        /// <summary>
        /// 未訪問地点などを探索する。
        /// </summary>
        Explore = 201,

        /// <summary>
        /// プレイヤーを直接追跡する。
        /// </summary>
        Chase = 300,

        /// <summary>
        /// プレイヤーの進行先へ先回りする。
        /// </summary>
        Intercept = 301,

        /// <summary>
        /// 脅威から逃走する。
        /// </summary>
        Escape = 400,

        /// <summary>
        /// 自身の縄張りへ帰還する。
        /// </summary>
        ReturnToTerritory = 500
    }
}
